// Regression tests migrated to exercise the public Sci API.
// Preserve the independently computed reference values as originally recorded.
#![allow(clippy::excessive_precision)]

#[cfg(test)]
mod hyp1f1_benchmark_tests {
    #[test]
    fn exact_seeded_benchmark_inputs_match_high_precision_series() {
        // 120-digit Decimal evaluation of the defining series, using the exact
        // binary64 values generated by benches/common/mod.rs (seeds 52-54).
        let mut count = 0;
        for (index, row) in include_str!("../../../tests/fixtures/hyp1f1_bench_exact.csv")
            .lines()
            .skip(1)
            .enumerate()
        {
            let values: Vec<f64> = row.split(',').map(|v| v.parse().unwrap()).collect();
            let (a, b, x, expected) = (values[0], values[1], values[2], values[3]);
            let actual = sci_special::hypergeometric::hyp1f1(a, b, x);
            assert!(
                (actual - expected).abs() <= 2e-13 * expected.abs(),
                "case {index}: hyp1f1({a}, {b}, {x}) = {actual}, expected {expected}"
            );
            count += 1;
        }
        assert_eq!(count, 256);
    }
}

#[test]
fn it2i0k0_tail_matches_high_precision_defining_integral() {
    // Independent 45-digit mpmath quadrature of ∫_x^∞ K0(t)/t dt,
    // using mpmath.besselk (not Cephes k0e) and 16-point Gauss-Legendre
    // integration on shifted intervals [0,4], [4,12], [12,32], [32,64].
    // For points 1e-5 from an anchor, the corresponding direct K0/t
    // integral over that short interval uses composite Simpson;
    // the neglected remainder beyond 64 is < 1e-27 relative.
    let cases = [
        (3.99999, 2.1204502661632774e-3),
        (4.0, 2.1204223667821441e-3),
        (4.00001, 2.1203944677828463e-3),
        (5.99999, 1.6996850000951825e-4),
        (6.0, 1.6996642667271107e-4),
        (6.00001, 1.6996435336175809e-4),
        (7.99999, 1.5660321697170718e-5),
        (8.0, 1.5660138607703697e-5),
        (8.00001, 1.5659955520407652e-5),
        (14.99999, 5.983667035091793e-9),
        (15.0, 5.983601571155363e-9),
        (15.00001, 5.983536107938692e-9),
        (19.99999, 2.6790778782837200e-11),
        (20.0, 2.6790491719403897e-11),
        (20.00001, 2.6790204659055655e-11),
        (40.0, 2.0242046145399134e-20),
        (100.0, 4.5885214327746765e-47),
        (700.0, 6.656866442254127e-309),
    ];
    for (x, expected) in cases {
        let actual = sci_special::bessel::it2i0k0(x).1;
        // The x<4 case uses the unmodified legacy special-function
        // kernel; the remaining cases use the new scaled interpolation.
        let max_relative = if x < 4.0 { 5e-11 } else { 8e-13 };
        assert!(
            actual.is_finite() && (actual / expected - 1.0).abs() < max_relative,
            "it2i0k0 tail at x={x}: actual={actual:e}, reference={expected:e}, rtol={max_relative:e}"
        );
    }
}

#[test]
fn integral_fast_paths_match_independent_quadrature() {
    // 60-digit mpmath quadrature of the defining integrals, including the
    // binary64 / double-double and quadrature transitions.
    let airy_cases: &[(f64, [f64; 4])] = &[
        (
            4.0,
            [
                0.33289264538612213,
                48.21947526380343,
                0.4780074964292617,
                -0.05076005849528754,
            ],
        ),
        (
            4.0001,
            [
                0.3328927405327147,
                48.227860780633575,
                0.4780004738291565,
                -0.05072083444162559,
            ],
        ),
        (
            5.0,
            [
                0.33328759030591787,
                321.47831857046515,
                0.7178822045478277,
                0.15873093858143864,
            ],
        ),
        (
            8.0,
            [
                0.33333331724248355,
                440065.2580490418,
                0.7839825965711773,
                -0.014756446293227662,
            ],
        ),
        // At these arguments the former xsf backend loses the Ai
        // integral to catastrophic cancellation (it even turns negative).
        // 75-digit independent integration gives the first two values.
        (
            9.150025219244185,
            [
                0.33333333282847294,
                11440088.204963699,
                0.5664051572423718,
                0.03741902951385366,
            ],
        ),
        (
            10.0,
            [
                0.33333333329916903,
                147809803.1074067,
                0.7656984031342129,
                0.015040424806140021,
            ],
        ),
        (
            10.0001,
            [
                0.33333333329918006,
                147855374.36970156,
                0.7657024222766693,
                0.015008956226629616,
            ],
        ),
    ];
    for &(x, reference) in airy_cases {
        for (actual, expected) in sci_special::wave::itairy(x).into_iter().zip(reference) {
            assert!(
                (actual - expected).abs() <= 2e-13 * expected.abs().max(1.0),
                "Airy x={x}: actual={actual:e}, reference={expected:e}"
            );
        }
        let reflected = sci_special::wave::itairy(-x);
        let positive = sci_special::wave::itairy(x);
        assert_eq!(
            reflected,
            [-positive[2], -positive[3], -positive[0], -positive[1]]
        );
    }
    for (x, reference) in [
        (10.0, 2.5189576695087033),
        (10.0001, 2.5189695426010035),
        (16.0, 2.74642640255143),
        (20.0, 2.5484516922939573),
        (23.9999, 2.8918158419558813),
        (24.0, 2.8918032068700988),
        (24.0001, 2.8917905712427223),
    ] {
        let actual = sci_special::bessel::itstruve0(x);
        assert!(
            (actual - reference).abs() < 3e-12 * reference,
            "Struve x={x}: actual={actual:e}, reference={reference:e}"
        );
        assert_eq!(actual, sci_special::bessel::itstruve0(-x));
    }
    for (x, reference) in [
        (4.0, 0.002120422366782144),
        (6.0, 0.00016996642667271107),
        (10.0, 1.5629281430764054e-6),
        (20.0, 2.6790491719403897e-11),
    ] {
        let actual = sci_special::bessel::it2i0k0(x).1;
        assert!(
            (actual / reference - 1.0).abs() < 2e-12,
            "Bessel tail x={x}: actual={actual:e}, reference={reference:e}"
        );
    }
    for (h, a, reference) in [
        (0.5, 0.35, 0.04705434925202117),
        (0.5, 0.36, 0.04828218926612005),
        (2.0, 0.35, 0.006717037127945251),
        (2.0, 0.8, 0.010631958144605746),
        (1.0, 1.0, 0.06674188216570097),
        (0.5, 2.0, 0.1415806036539784),
        (6.0, 0.5, 4.922418609131739e-10),
        // Independent 65-digit quadrature; small-a/T4 transition cases.
        (0.2, 0.01, 0.0015599816026939633),
        (0.2, 0.15, 0.023223884618078363),
        (0.2, 0.1500000000001, 0.023223884618093615),
        (0.2, 0.3, 0.045441628418078514),
        (0.2, 0.3000000000001, 0.045441628418092801),
        (0.2, 0.5, 0.072217376747556905),
        (0.2, 0.5000000000001, 0.072217376747569326),
        (3.0, 0.499999999999, 0.00060512137858473563),
        (3.000000000001, 0.499999999999, 0.00060512137858281584),
        (5.99999, 0.29999999, 4.6128442599634287e-10),
        (6.00001, 0.29999999, 4.6122803333658172e-10),
        (8.0, 0.1, 1.8141981844090175e-16),
        (3.1, 0.5, 0.00043836729077556324),
        // Large a, saturation, and cancellation in the reflection.
        (1.0, 2.0, 0.078468186993084096),
        (1.0, 8.0, 0.079327626965728523),
        (1.0, 8.499999, 0.079327626965728523),
        (1.0, 8.500001, 0.079327626965728523),
        (8.0, 1.00001, 3.11048028713589e-16),
        (8.49999, 1.0000001, 4.7401757402369784e-18),
        (8.5, 1.0000001, 4.739767411101659e-18),
        (0.01, 100.0, 0.24767297891854384),
        (0.001, 1000.0, 0.24976729086693258),
        (2.0, 4.0, 0.011375065974089603),
        (5.0, 3.0, 1.4332578593959696e-07),
    ] {
        let actual = sci_special::probability::owens_t(h, a);
        assert!(
            (actual / reference - 1.0).abs() < 2e-12,
            "Owen h={h}, a={a}: actual={actual:e}, reference={reference:e}"
        );
        assert_eq!(-actual, sci_special::probability::owens_t(-h, -a));
    }
    assert_eq!(sci_special::probability::owens_t(0.0, f64::INFINITY), 0.25);
    assert_eq!(
        sci_special::probability::owens_t(0.0, f64::NEG_INFINITY),
        -0.25
    );
    assert_eq!(sci_special::probability::owens_t(f64::INFINITY, 2.0), 0.0);
    assert_eq!(
        sci_special::probability::owens_t(f64::INFINITY, -2.0).to_bits(),
        (-0.0_f64).to_bits()
    );
    assert_eq!(
        sci_special::probability::owens_t(2.0, 0.0).to_bits(),
        0.0_f64.to_bits()
    );
    assert_eq!(
        sci_special::probability::owens_t(2.0, -0.0).to_bits(),
        (-0.0_f64).to_bits()
    );
    assert!(sci_special::probability::owens_t(f64::NAN, 2.0).is_nan());
    assert!(sci_special::probability::owens_t(1.0, f64::NAN).is_nan());
}

#[test]
fn legendre_q_short_interior_table_matches_independent_high_precision_values() {
    // Independently evaluated with mpmath 1.4.1 at 70 decimal digits:
    // legenq(n, 0, x, type=2), with its derivative obtained from mpmath's
    // neighboring Legendre-Q values and the analytic derivative identity.
    // Include both signs, low degrees, and the n=32 benchmark endpoint.
    type ReferenceDegree = (usize, f64, f64);
    let references: &[(f64, &[ReferenceDegree])] = &[
        (
            0.3,
            &[
                (0, 0.3095196042031117, 1.098901098901099),
                (1, -0.9071441187390665, 0.6391899338734414),
                (2, -0.5629746555341358, -1.6225312573161006),
                (8, 0.22875767420043008, -3.314929565594577),
                (16, -0.3000491852831814, 1.656448471025743),
                (32, -0.10372428176230092, -6.823357061057721),
            ],
        ),
        (
            -0.7,
            &[
                (0, -0.8673005276940532, 1.9607843137254901),
                (1, -0.39288963061416276, -2.2398495473018963),
                (2, 0.8461843759918975, 0.7821154218830019),
                (8, -0.16067491577070817, 5.862727358569286),
                (16, -0.08500596322385005, 8.265630257433847),
                (32, -0.01856818131185757, 11.8231467637495),
            ],
        ),
    ];
    for &(x, degrees) in references {
        let (values, slopes) = sci_special::orthogonal::lqn(32, x).unwrap();
        assert_eq!(values.len(), 33);
        assert_eq!(slopes.len(), 33);
        for &(degree, expected_value, expected_slope) in degrees {
            for (actual, expected, part) in [
                (values[degree], expected_value, "value"),
                (slopes[degree], expected_slope, "derivative"),
            ] {
                let tolerance = 2e-12 * expected.abs().max(1e-4);
                assert!(
                    (actual - expected).abs() <= tolerance,
                    "Q_{degree} {part} at x={x}: got={actual:.17e}, expected={expected:.17e}, tolerance={tolerance:.3e}"
                );
            }
        }
    }
}

#[test]
fn legendre_q_optimized_table_preserves_special_and_exterior_domains() {
    let (positive, positive_slopes) = sci_special::orthogonal::lqn(8, 1.5).unwrap();
    let (negative, negative_slopes) = sci_special::orthogonal::lqn(8, -1.5).unwrap();
    let expected_q0 = 0.5 * (5.0_f64).ln();
    for (actual, expected, label) in [
        (positive[0], expected_q0, "Q0(1.5)"),
        (negative[0], -expected_q0, "Q0(-1.5)"),
        (positive_slopes[0], -0.8, "Q0'(1.5)"),
        (negative_slopes[0], -0.8, "Q0'(-1.5)"),
    ] {
        assert!(
            (actual - expected).abs() <= 2e-14 * expected.abs(),
            "{label}: actual={actual}, expected={expected}"
        );
    }
    for degree in 0..=8 {
        let phase = if degree % 2 == 0 { -1.0 } else { 1.0 };
        let tolerance = 2e-13 * positive[degree].abs().max(1e-14);
        assert!(
            (negative[degree] - phase * positive[degree]).abs() <= tolerance,
            "Q_{degree} parity at x=±1.5"
        );
        let tolerance = 2e-13 * positive_slopes[degree].abs().max(1e-14);
        assert!(
            (negative_slopes[degree] + phase * positive_slopes[degree]).abs() <= tolerance,
            "Q_{degree} derivative parity at x=±1.5"
        );
    }
    for x in [f64::NAN, f64::INFINITY, f64::NEG_INFINITY] {
        let (values, slopes) = sci_special::orthogonal::lqn(8, x).unwrap();
        assert!(values.iter().all(|value| value.is_nan()), "Q_n at {x}");
        assert!(slopes.iter().all(|value| value.is_nan()), "Q'_n at {x}");
    }
    // Existing pole convention: the backend returns 1e300 at both ±1.
    for x in [-1.0, 1.0] {
        let (values, slopes) = sci_special::orthogonal::lqn(8, x).unwrap();
        assert!(values.iter().all(|&value| value == 1e300));
        assert!(slopes.iter().all(|&value| value == 1e300));
    }
}
